// kubejs/startup_scripts/autogeneratedyabbadabbadoo/framework/registry.js

global.FLAGS = {
  Ingot:       { id: 'ingot',        display: 'Ingot' },
  Plate:       { id: 'plate',        display: 'Plate' },
  Rod:         { id: 'rod',          display: 'Rod' },
  LongRod:     { id: 'long_rod',     display: 'Long Rod' },
  DoublePlate: { id: 'double_plate', display: 'Double Plate' },
  DensePlate:  { id: 'dense_plate',  display: 'Dense Plate' },
  Wire:        { id: 'wire',         display: 'Wire' },
  Spool:       { id: 'wire_spool',   display: 'Wire Spool' },
  Foil:        { id: 'foil',         display: 'Foil' },
  Bolt:        { id: 'bolt',         display: 'Bolt' },
  Screw:       { id: 'screw',        display: 'Screw' },
  Gear:        { id: 'gear',         display: 'Gear' },
  SmallGear:   { id: 'small_gear',   display: 'Small Gear' },
  Nugget:      { id: 'nugget',       display: 'Nugget' },
  Nanoswarm:   { id: 'nanoswarm',    display: 'Nano Swarm' },
  Block:       { id: 'block',        display: 'Block' },
}

// Material forms: determines the primary material item.
global.MATERIAL_FORMS = ['ingot', 'gem']

global.FLAG_DEPS = {
  Plate:       ['Ingot'],
  Rod:         ['Ingot'],
  LongRod:     ['Rod'],
  DoublePlate: ['Plate'],
  DensePlate:  ['Plate'],
  Spool:       ['Wire'],
  Foil:        ['Plate'],
  Bolt:        ['Rod'],
  Screw:       ['Bolt'],
  Gear:        ['Plate', 'Rod'],
  SmallGear:   ['Plate', 'LongRod'],
  Nugget:      ['Ingot'],
  Wire:        ['Plate'],
  Nanoswarm:   ['Nugget', 'Bolt']
}

global.MODIFIER_FLAGS = ['noHot', 'noIngot', 'noDust']
global.MATERIAL_SETS = ['shiny', 'metallic', 'dull']
global.MATERIALS = []

var validateFlags = function(id, flag, itemFlags) {
  var deps = global.FLAG_DEPS[flag]
  if (!deps) return

  for (var i = 0; i < deps.length; i++) {
    var dep = deps[i]

    if (!itemFlags.includes(dep)) {
      console.error(
        '[MKWRC Materials] ' + id +
        ': flag ' + flag + ' requires ' + dep + ' but it\'s missing!'
      )
    } else {
      validateFlags(id, dep, itemFlags)
    }
  }
}

global.registerMaterial = function(id, data) {
  var display = data.display
  var flags = data.flags || []
  var color = data.color
  var set = data.set

  // Material form defaults to ingot.
  var form = data.form || 'ingot'

  if (!global.MATERIAL_FORMS.includes(form)) {
    console.error(
      '[MKWRC Materials] ' + id +
      ': unknown material form \'' + form +
      '\', defaulting to ingot'
    )
    form = 'ingot'
  }

  var resolvedSet = global.MATERIAL_SETS.includes(set) ? set : 'metallic'

  if (!global.MATERIAL_SETS.includes(set)) {
    console.error(
      '[MKWRC Materials] ' + id +
      ': unknown material set \'' + set +
      '\', defaulting to metallic'
    )
  }

  var itemFlags = flags.filter(function(f) {
    return !global.MODIFIER_FLAGS.includes(f)
  })

  for (var i = 0; i < itemFlags.length; i++) {
    var flag = itemFlags[i]

    if (!global.FLAGS[flag]) {
      console.error('[MKWRC Materials] ' + id + ': unknown flag \'' + flag + '\'')
      continue
    }

    validateFlags(id, flag, itemFlags)
  }

  global.MATERIALS.push({
    id: id,
    display: display,

    // Material form
    form: form,

    element: data.element || null,
    composition: data.composition || null,

    processing: data.processing || {
      energy: 1.0,
      duration: 1.0
    },

    // Physical properties
    temperature: data.temperature == null ? 303 : data.temperature,
    liquid: data.liquid === true,
    molten: data.molten === true,
    gaseous: data.gaseous === true,

    // Gameplay properties
    toxicity: data.toxicity || null,

    flags: flags,
    color: color,
    set: resolvedSet
  })
}

